import os, ctypes, subprocess
import numpy as np

_DIR = os.path.dirname(os.path.abspath(__file__))
_SO = os.path.join(_DIR, "lap", "libfin.so")
if not os.path.exists(_SO):
    subprocess.run(["cc", "-O3", "-march=native", "-ffast-math", "-funroll-loops", "-DEPS0=0.02", "-DEPSF=3e-4", "-DEPSDIV=4", "-shared", "-fPIC", "-o", _SO,
                    os.path.join(_DIR, "lap", "fin.c")], check=False)
_lib = ctypes.CDLL(_SO)
_lib.slap.argtypes = [ctypes.c_int, ctypes.c_void_p, ctypes.c_double, ctypes.c_int, ctypes.c_void_p]
_lib.slap.restype = ctypes.c_int


def _fallback(a, b, M):
    import ot
    return ot.lp.emd(a, b, np.ascontiguousarray(M, dtype=np.float64), check_marginals=False)


class Solver:
    def solve(self, problem, **kwargs):
        a = np.asarray(problem["source_weights"], dtype=np.float64)
        b = np.asarray(problem["target_weights"], dtype=np.float64)
        M = problem["cost_matrix"]
        n = a.shape[0]
        a0 = a[0]
        if (b.shape[0] != n or n < 2 or a0 <= 0 or a.min() != a0 or a.max() != a0 or b.min() != a0 or b.max() != a0):
            return {"transport_plan": _fallback(a, b, M)}
        M = np.ascontiguousarray(M, dtype=np.float64)
        rs = np.empty(n, dtype=np.int32)
        f = _lib.slap(n, M.ctypes.data, 0.14, 6, rs.ctypes.data)
        if f:
            return {"transport_plan": _fallback(a, b, M)}
        G = np.zeros((n, n))
        G[np.arange(n), rs] = a[0]
        return {"transport_plan": G}

