#include <stdlib.h>
#include <string.h>
#define BIG 1e300
/* LAPJV dense. cost n*n row-major. outputs rowsol (row->col). */
int lapjv(int n, const double *cost, int *rowsol){
  int *colsol=malloc(n*sizeof(int)), *free_=malloc(n*sizeof(int)), *collist=malloc(n*sizeof(int)),
      *matches=calloc(n,sizeof(int)), *pred=malloc(n*sizeof(int));
  double *v=malloc(n*sizeof(double)), *d=malloc(n*sizeof(double));
  int i,j,j1,j2,i0,k,f,numfree=0,prvnumfree,f0,i1,low,up,last,endofpath;
  double min,h,umin,usubmin,v2;
  /* column reduction */
  for(j=n-1;j>=0;j--){
    min=cost[j]; i1=0;
    for(i=1;i<n;i++) if(cost[i*n+j]<min){min=cost[i*n+j];i1=i;}
    v[j]=min;
    if(++matches[i1]==1){rowsol[i1]=j;colsol[j]=i1;} else colsol[j]=-1;
  }
  /* reduction transfer */
  for(i=0;i<n;i++){
    if(matches[i]==0) free_[numfree++]=i;
    else if(matches[i]==1){
      j1=rowsol[i]; min=BIG; const double*c=cost+(size_t)i*n;
      for(j=0;j<n;j++) if(j!=j1){ double t=c[j]-v[j]; if(t<min)min=t; }
      v[j1]-=min;
    }
  }
  /* augmenting row reduction */
  int loopcnt=0;
  do{
    loopcnt++; k=0; prvnumfree=numfree; numfree=0;
    while(k<prvnumfree){
      i=free_[k++]; const double*c=cost+(size_t)i*n;
      umin=c[0]-v[0]; j1=0; usubmin=BIG; j2=-1;
      for(j=1;j<n;j++){ h=c[j]-v[j];
        if(h<usubmin){ if(h>=umin){usubmin=h;j2=j;} else {usubmin=umin;umin=h;j2=j1;j1=j;} } }
      i0=colsol[j1];
      if(umin<usubmin) v[j1]=v[j1]-(usubmin-umin);
      else if(i0>=0){ j1=j2; i0=colsol[j2]; }
      rowsol[i]=j1; colsol[j1]=i;
      if(i0>=0){ if(umin<usubmin) free_[--k]=i0; else free_[numfree++]=i0; }
    }
  }while(loopcnt<2);
  /* augmentation */
  for(f=0;f<numfree;f++){
    int freerow=free_[f]; const double*c=cost+(size_t)freerow*n;
    for(j=0;j<n;j++){ d[j]=c[j]-v[j]; pred[j]=freerow; collist[j]=j; }
    low=0; up=0; int unassignedfound=0;
    do{
      if(up==low){
        last=low-1; min=d[collist[up++]];
        for(k=up;k<n;k++){ j=collist[k]; h=d[j];
          if(h<=min){ if(h<min){up=low;min=h;} collist[k]=collist[up]; collist[up++]=j; } }
        for(k=low;k<up;k++) if(colsol[collist[k]]<0){ endofpath=collist[k]; unassignedfound=1; break; }
      }
      if(!unassignedfound){
        j1=collist[low++]; i=colsol[j1]; const double*ci=cost+(size_t)i*n;
        h=ci[j1]-v[j1]-min;
        for(k=up;k<n;k++){ j=collist[k]; v2=ci[j]-v[j]-h;
          if(v2<d[j]){ pred[j]=i;
            if(v2==min){ if(colsol[j]<0){endofpath=j;unassignedfound=1;break;}
              else { collist[k]=collist[up]; collist[up++]=j; } }
            d[j]=v2; } }
      }
    }while(!unassignedfound);
    for(k=0;k<=last;k++){ j1=collist[k]; v[j1]+=d[j1]-min; }
    do{ i=pred[endofpath]; colsol[endofpath]=i; j1=endofpath; endofpath=rowsol[i]; rowsol[i]=j1; }while(i!=freerow);
  }
  free(colsol);free(free_);free(collist);free(matches);free(pred);free(v);free(d);
  return 0;
}
