#include <stdlib.h>
#include <string.h>
#include <math.h>
#define INF 1e300
typedef struct {double d; int j;} HE;
static void hpush(HE*h,int*n,double d,int j){int i=(*n)++;while(i>0){int p=(i-1)>>1;if(h[p].d<=d)break;h[i]=h[p];i=p;}h[i].d=d;h[i].j=j;}
static HE hpop(HE*h,int*n){HE top=h[0];HE last=h[--(*n)];int i=0,m=*n;for(;;){int c=2*i+1;if(c>=m)break;if(c+1<m&&h[c+1].d<h[c].d)c++;if(h[c].d>=last.d)break;h[i]=h[c];i=c;}h[i]=last;return top;}

/* select k smallest indices of row (length n) into out */
static void ksmall(const double*row,int n,int k,int*idx,int*out){
  for(int j=0;j<n;j++)idx[j]=j;
  int lo=0,hi=n-1;
  while(lo<hi){
    double piv=row[idx[(lo+hi)>>1]];int i=lo,j=hi;
    while(i<=j){while(row[idx[i]]<piv)i++;while(row[idx[j]]>piv)j--;if(i<=j){int t=idx[i];idx[i]=idx[j];idx[j]=t;i++;j--;}}
    if(k-1<=j)hi=j;else if(k-1>=i)lo=i;else break;
  }
  memcpy(out,idx,k*sizeof(int));
}

/* returns 0 ok, 1 fail */
int slap(int n,const double*C,int k,int*rowsol){
  if(k>n)k=n;
  int *idx=malloc(n*sizeof(int));
  /* build adjacency: row kNN + col kNN */
  int *deg=calloc(n,sizeof(int));
  int *rk=malloc((size_t)n*k*sizeof(int)), *ck=malloc((size_t)n*k*sizeof(int));
  double *col=malloc(n*sizeof(double));
  for(int i=0;i<n;i++)ksmall(C+(size_t)i*n,n,k,idx,rk+(size_t)i*k);
  for(int j=0;j<n;j++){for(int i=0;i<n;i++)col[i]=C[(size_t)i*n+j];ksmall(col,n,k,idx,ck+(size_t)j*k);}
  /* mark to dedupe */
  int *start=malloc((n+1)*sizeof(int));
  int *mark=malloc(n*sizeof(int)); for(int j=0;j<n;j++)mark[j]=-1;
  for(int i=0;i<n;i++)deg[i]=k;
  for(int j=0;j<n;j++)for(int t=0;t<k;t++)deg[ck[(size_t)j*k+t]]++;
  start[0]=0;for(int i=0;i<n;i++)start[i+1]=start[i]+deg[i];
  int *adj=malloc((size_t)start[n]*sizeof(int)); int *fill=calloc(n,sizeof(int));
  for(int i=0;i<n;i++)for(int t=0;t<k;t++)adj[start[i]+fill[i]++]=rk[(size_t)i*k+t];
  for(int j=0;j<n;j++)for(int t=0;t<k;t++){int i=ck[(size_t)j*k+t];adj[start[i]+fill[i]++]=j;}
  /* dedupe per row */
  int *cnt=malloc(n*sizeof(int));
  for(int i=0;i<n;i++){int w=start[i];for(int p=start[i];p<start[i]+fill[i];p++){int j=adj[p];if(mark[j]!=i){mark[j]=i;adj[w++]=j;}}cnt[i]=w-start[i];}
  double *ac=malloc((size_t)start[n]*sizeof(double));
  for(int i=0;i<n;i++)for(int p=start[i];p<start[i]+cnt[i];p++)ac[p]=C[(size_t)i*n+adj[p]];
  /* potentials */
  double *u=calloc(n,sizeof(double)),*v=malloc(n*sizeof(double));
  int *colsol=malloc(n*sizeof(int));
  for(int j=0;j<n;j++)colsol[j]=-1;
  for(int i=0;i<n;i++)rowsol[i]=-1;
  for(int j=0;j<n;j++){double m=INF;int am=0;for(int i=0;i<n;i++){double c=C[(size_t)i*n+j];if(c<m){m=c;am=i;}}v[j]=m;
    if(rowsol[am]<0){rowsol[am]=j;colsol[j]=am;}}
  double *d=malloc(n*sizeof(double)); for(int j=0;j<n;j++)d[j]=INF;
  int *pred=malloc(n*sizeof(int)); char *done=calloc(n,1);
  int *touched=malloc(n*sizeof(int)); int *SR=malloc(n*sizeof(int));
  HE *heap=malloc(((size_t)start[n]+n)*sizeof(HE));
  int fail=0;
  for(int r=0;r<n&&!fail;r++){
    if(rowsol[r]>=0)continue;
    int nt=0,nsr=0,hn=0; int i=r; double minVal=0; int sink=-1;
    for(;;){
      SR[nsr++]=i;
      for(int p=start[i];p<start[i]+cnt[i];p++){int j=adj[p];if(done[j])continue;
        double nd=minVal+ac[p]-u[i]-v[j];
        if(nd<d[j]){if(d[j]==INF)touched[nt++]=j;d[j]=nd;pred[j]=i;hpush(heap,&hn,nd,j);}}
      int j=-1;
      while(hn>0){HE e=hpop(heap,&hn);if(!done[e.j]&&e.d==d[e.j]){j=e.j;break;}}
      if(j<0){fail=1;break;}
      done[j]=1; minVal=d[j];
      if(colsol[j]<0){sink=j;break;}
      i=colsol[j];
    }
    if(fail)break;
    /* update duals */
    u[r]+=minVal;
    for(int t=1;t<nsr;t++){int ii=SR[t];u[ii]+=minVal-d[rowsol[ii]];}
    for(int t=0;t<nt;t++){int j=touched[t];if(done[j])v[j]-=minVal-d[j];d[j]=INF;done[j]=0;}
    /* augment */
    int j=sink;
    for(;;){int ii=pred[j];colsol[j]=ii;int tmp=rowsol[ii];rowsol[ii]=j;j=tmp;if(ii==r)break;}
  }
  if(!fail){
    /* dense dual check */
    for(int i=0;i<n&&!fail;i++){const double*c=C+(size_t)i*n;double ui=u[i];
      for(int j=0;j<n;j++) if(c[j]-ui-v[j]< -1e-12){fail=1;break;}}
  }
  free(idx);free(deg);free(rk);free(ck);free(col);free(start);free(mark);free(adj);free(fill);free(cnt);free(ac);
  free(u);free(v);free(colsol);free(d);free(pred);free(done);free(touched);free(SR);free(heap);
  return fail;
}
