#include <stdlib.h>
#include <string.h>
#define INF 1e300
typedef struct {double d; int j;} HE;
static inline void hpush(HE*h,int*n,double d,int j){int i=(*n)++;while(i>0){int p=(i-1)>>1;if(h[p].d<=d)break;h[i]=h[p];i=p;}h[i].d=d;h[i].j=j;}
static inline HE hpop(HE*h,int*n){HE top=h[0];HE last=h[--(*n)];int i=0,m=*n;for(;;){int c=2*i+1;if(c>=m)break;if(c+1<m&&h[c+1].d<h[c].d)c++;if(h[c].d>=last.d)break;h[i]=h[c];i=c;}h[i]=last;return top;}

typedef struct {int *j; double *c; int n, cap;} Row;
static void addedge(Row*r,int j,double c){if(r->n==r->cap){r->cap=r->cap?2*r->cap:8;r->j=realloc(r->j,r->cap*sizeof(int));r->c=realloc(r->c,r->cap*sizeof(double));}r->j[r->n]=j;r->c[r->n]=c;r->n++;}

int slap(int n,const double*C,int k,int*rowsol,int*stats){
  Row*R=calloc(n,sizeof(Row));
  double *u=calloc(n,sizeof(double)),*v=malloc(n*sizeof(double));
  int *colsol=malloc(n*sizeof(int));
  for(int j=0;j<n;j++){colsol[j]=-1;v[j]=INF;}
  for(int i=0;i<n;i++)rowsol[i]=-1;
  int *am=malloc(n*sizeof(int));
  for(int i=0;i<n;i++){const double*c=C+(size_t)i*n;for(int j=0;j<n;j++)if(c[j]<v[j]){v[j]=c[j];am[j]=i;}}
  for(int j=0;j<n;j++){int i=am[j];if(rowsol[i]<0){rowsol[i]=j;colsol[j]=i;}}
  /* initial edges: per row, entries with reduced cost below threshold: take k smallest c-v */
  double *rc=malloc(n*sizeof(double)); int*idx=malloc(n*sizeof(int));
  for(int i=0;i<n;i++){const double*c=C+(size_t)i*n;for(int j=0;j<n;j++){rc[j]=c[j]-v[j];idx[j]=j;}
    int lo=0,hi=n-1,kk=k<n?k:n;
    while(lo<hi){double piv=rc[idx[(lo+hi)>>1]];int a=lo,b=hi;
      while(a<=b){while(rc[idx[a]]<piv)a++;while(rc[idx[b]]>piv)b--;if(a<=b){int t=idx[a];idx[a]=idx[b];idx[b]=t;a++;b--;}}
      if(kk-1<=b)hi=b;else if(kk-1>=a)lo=a;else break;}
    for(int t=0;t<kk;t++)addedge(&R[i],idx[t],c[idx[t]]);
    if(rowsol[i]>=0){int f=0;for(int t=0;t<kk;t++)if(idx[t]==rowsol[i])f=1;if(!f)addedge(&R[i],rowsol[i],c[rowsol[i]]);}
  }
  double *d=malloc(n*sizeof(double)); for(int j=0;j<n;j++)d[j]=INF;
  int *pred=malloc(n*sizeof(int)); char *done=calloc(n,1);
  int *touched=malloc(n*sizeof(int)); int *SR=malloc(n*sizeof(int));
  int heapcap=16*n; HE *heap=malloc(heapcap*sizeof(HE));
  int fail=0,rounds=0,augs=0;
  for(;;){
    rounds++;
    for(int r=0;r<n&&!fail;r++){
      if(rowsol[r]>=0)continue;
      augs++;
      int nt=0,nsr=0,hn=0; int i=r; double minVal=0; int sink=-1;
      for(;;){
        SR[nsr++]=i; double base=minVal-u[i];
        Row*rw=&R[i];
        for(int p=0;p<rw->n;p++){int j=rw->j[p];if(done[j])continue;
          double nd=base+rw->c[p]-v[j];
          if(nd<d[j]){if(d[j]==INF)touched[nt++]=j;d[j]=nd;pred[j]=i;
            if(hn==heapcap){heapcap*=2;heap=realloc(heap,heapcap*sizeof(HE));}
            hpush(heap,&hn,nd,j);}}
        int j=-1;
        while(hn>0){HE e=hpop(heap,&hn);if(!done[e.j]&&e.d==d[e.j]){j=e.j;break;}}
        if(j<0){fail=1;break;}
        done[j]=1; minVal=d[j];
        if(colsol[j]<0){sink=j;break;}
        i=colsol[j];
      }
      if(fail)break;
      u[r]+=minVal;
      for(int t=1;t<nsr;t++){int ii=SR[t];u[ii]+=minVal-d[rowsol[ii]];}
      for(int t=0;t<nt;t++){int j=touched[t];if(done[j])v[j]-=minVal-d[j];d[j]=INF;done[j]=0;}
      int j=sink;
      for(;;){int ii=pred[j];colsol[j]=ii;int tmp=rowsol[ii];rowsol[ii]=j;j=tmp;if(ii==r)break;}
    }
    if(fail)break;
    /* dense check & repair */
    int viol=0;
    for(int i=0;i<n;i++){const double*c=C+(size_t)i*n;double ui=u[i];double m=0;int any=0;
      for(int j=0;j<n;j++){double t=c[j]-ui-v[j];if(t< -1e-12){any=1;if(t<m)m=t;}}
      if(any){viol++;
        for(int j=0;j<n;j++){double t=c[j]-ui-v[j];if(t<-1e-12)addedge(&R[i],j,c[j]);}
        u[i]+=m; int j0=rowsol[i]; colsol[j0]=-1; rowsol[i]=-1;}
    }
    if(!viol)break;
    if(rounds>50){fail=1;break;}
  }
  if(stats){stats[0]=rounds;stats[1]=augs;}
  for(int i=0;i<n;i++){free(R[i].j);free(R[i].c);}
  free(R);free(u);free(v);free(colsol);free(am);free(rc);free(idx);free(d);free(pred);free(done);free(touched);free(SR);free(heap);
  return fail;
}
