      if(k>=kmin||k==n)break; th=m+(th-m)*2;}
    cnt[i]=k;
  }
  t1=now();TT[1]+=t1-t0;t0=t1;
  for(int j=0;j<n;j++)p[j]=-v[j];
  double eps=EPS0; long bids=0; int nf;
  for(int i=0;i<n;i++)rowsol[i]=-1; for(int j=0;j<n;j++)colsol[j]=-1;
  int fail=0;
